typedef uint32_t u32; typedef uint64_t u64;
static u32 P; static u64 im;
static inline u32 mulmod(u32 a,u32 b){ u64 x=(u64)a*b; u64 q=(u64)(((__uint128_t)x*(__uint128_t)im)>>64); u32 r=(u32)(x-q*(u64)P); if(r>=P)r-=P; return r; }
static inline u32 powmod(u32 base,u32 e){ if(base==0)return 0; if(base==1)return 1; u32 r=1,b=base; while(e){ if(e&1)r=mulmod(r,b); e>>=1; if(e)b=mulmod(b,b);} return r; }

vector<u32> getPrimes(u32 N){
  vector<char> comp(N+1,0); vector<u32> pr;
  for(u32 i=2;i<=N;i++){ if(!comp[i]){ pr.push_back(i); if((u64)i*i<=N) for(u64 j=(u64)i*i;j<=N;j+=i) comp[(size_t)j]=1; } }
  return pr;
}

u32 bruteXor(u32 N, const vector<u32>& pr, const vector<u32>& fp){
  vector<u32> f(N+1,1);
  for(u32 n=2;n<=N;n++){
    u32 x=n; u32 val=1;
    for(size_t i=0;i<pr.size() && (u64)pr[i]*pr[i]<=x;i++){
      if(x%pr[i]==0){ u32 q=1; while(x%pr[i]==0){x/=pr[i]; q*=pr[i];} val=mulmod(val,fp[q]); }
    }
    if(x>1) val=mulmod(val,fp[x]);
    f[n]=val;
  }
  u32 ans=0; for(u32 n=1;n<=N;n++) ans ^= powmod(f[n],n);
  return ans;
}

u32 newXor(u32 N, const vector<u32>& pr, const vector<u32>& fp){
  vector<u32> A(N+1,1);
  for(u32 p: pr){
    u32 q=p;
    while(true){
      u32 v=fp[q];
      u32 h0=powmod(v,q);
      if(h0!=1){
        u32 lim=N/q;
        if(h0==0){
          if(lim<p){ u32 idx=q; for(u32 m=1;m<=lim;m++,idx+=q) A[idx]=0; }
          else { u32 step=q*p; for(u32 r=1;r<p;r++){ u32 idx=q*r; for(u32 m=r;m<=lim;m+=p,idx+=step) A[idx]=0; } }
        } else {
          if(lim<p){ u32 cur=1,idx=q; for(u32 m=1;m<=lim;m++,idx+=q){ cur=mulmod(cur,h0); A[idx]=mulmod(A[idx],cur);} }
          else { u32 hp=powmod(h0,p); u32 base=1; u32 step=q*p;
            for(u32 r=1;r<p;r++){ base=mulmod(base,h0); u32 cur=base, idx=q*r; for(u32 m=r;m<=lim;m+=p,idx+=step){ A[idx]=mulmod(A[idx],cur); cur=mulmod(cur,hp);} }
          }
        }
      }
      if(q>N/p) break; q*=p;
    }
  }
  u32 ans=0; for(u32 n=1;n<=N;n++) ans ^= A[n];
  return ans;
}

u32 origXor(u32 N, const vector<u32>& pr, const vector<u32>& fp){
  vector<u32> A(N+1,1);
  const int BLOCK=128; u32 tab[BLOCK];
  for(u32 p: pr){
    u32 pe=p;
    while(pe<=N){
      u32 v=fp[pe]; u32 c=powmod(v,pe);
      if(c!=1){
        u32 lim=N/pe;
        if(lim<(u32)BLOCK){
          u32 factor=1; u64 kk=1, idx=pe, next_bad=p;
          while(kk<=lim){ factor=mulmod(factor,c); if(kk!=next_bad) A[idx]=mulmod(A[idx],factor); else next_bad+=p; ++kk; idx+=pe; }
        } else {
          tab[0]=1; for(int i=1;i<BLOCK;i++) tab[i]=mulmod(tab[i-1],c);
          u32 cB=mulmod(tab[BLOCK-1],c);
          u32 base=c; u64 kk0=1, next_bad=p;
          while(kk0<=lim){
            int cnt=BLOCK; if(kk0+(u64)cnt-1>(u64)lim) cnt=(int)((u64)lim-kk0+1);
            u64 idx=pe*kk0; u64 kk=kk0;
            for(int i=0;i<cnt;i++,kk++,idx+=pe){ u32 factor=mulmod(base,tab[i]); if(kk!=next_bad) A[idx]=mulmod(A[idx],factor); else next_bad+=p; }
            base=mulmod(base,cB); kk0+=(u64)cnt;
          }
        }
      }
      if(pe>(u64)N/p) break; pe*=p;
    }
  }
  u32 ans=0; for(u32 n=1;n<=N;n++) ans ^= A[n];
  return ans;
}

